<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Verifikasi Izin Pulang</title><style>body{font-family:Arial,sans-serif;background:#f3f4f6;margin:0;padding:24px}.card{max-width:520px;margin:auto;background:#fff;border-radius:14px;padding:24px;box-shadow:0 5px 24px #0001}h1{color:#198754;font-size:24px}dt{font-weight:bold;color:#6c757d;margin-top:12px}dd{margin:3px 0 0;font-size:18px}.valid{background:#d1e7dd;color:#0f5132;padding:12px;border-radius:8px;font-weight:bold}</style></head><body><div class="card"><div class="valid">✓ IZIN PULANG TERCATAT</div><h1>Verifikasi Surat Izin</h1><dl><dt>Nama Siswa</dt><dd>{{ $permit->student->nama_lengkap }}</dd><dt>NIS / Kelas</dt><dd>{{ $permit->student->nis }} / {{ $permit->student->classroom->nama_kelas ?? '-' }}</dd><dt>Tanggal</dt><dd>{{ $permit->tanggal->format('d/m/Y') }}</dd><dt>Jenis</dt><dd>{{ $permit->tipe_izin === 'penuh' ? 'Pulang Penuh' : 'Izin Sementara' }}</dd><dt>Jam Keluar</dt><dd>{{ substr($permit->jam_keluar,0,5) }}</dd><dt>Alasan</dt><dd>{{ $permit->alasan }}</dd></dl><p>Surat ini telah tercatat di sistem sekolah.</p></div></body></html>
